let train1 = [],
  train2 = [],
  dailyFlow = [];

context.panel.data.series.forEach((s) => {
  if (s.refId === 'Train 1') {
    timeData = s.fields.find((f) => f.name === 'Time')?.values ?? [];
    train1 = s.fields.find((f) => f.name === 'Train 1')?.values ?? [];
  }
  if (s.refId === 'Train 2') {
    train2 = s.fields.find((f) => f.name === 'Train 2')?.values ?? [];
  }
  if (s.refId === 'Total Daily Flow') {
    dailyFlow =
      s.fields.find((f) => f.name === 'Total Daily Flow')?.values ?? [];
  }
  //Train 1
});

// Format dates
const formattedDates = timeData.map((d) => {
  const date = new Date(d); // Parse the ISO string directly
  // Extract date components in UTC
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth() + 1; // Month is zero-indexed
  const day = date.getUTCDate();
  // Return formatted date string as 'MM/DD/YYYY, HH:mm AM/PM'
  return `${month}/${day}/${year}`;
});

return {
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'cross',
    },
    formatter: function (params) {
      let tooltipText = `${params[0].axisValueLabel}<br/>`;
      params.forEach((item) => {
        let value = item.data === '-' ? '-' : `${item.data}K`; // Append 'K' to valid values
        tooltipText += `${item.marker} ${item.seriesName}: ${value} <br/>`;
      });
      return tooltipText;
    },
  },
  legend: {
    data: ['Train 1', 'Train 2', 'Total Daily Flow'],
  },
  grid: {
    left: '5%',
    right: '4%',
    bottom: '10%',
    containLabel: true,
  },
  xAxis: {
    type: 'category',
    data: formattedDates,
    axisLabel: {
      formatter: function (val) {
        const date = new Date(val);
        const month = date.getMonth() + 1; // Month is zero-indexed
        const day = date.getDate();
        return `${month}/${day}`;
      },
    },
  },
  yAxis: {
    type: 'value',
    name: 'm3/d',
    nameLocation: 'middle',
    nameGap: 55,
    nameTextStyle: {
      fontSize: 12,
      align: 'center',
      verticalAlign: 'middle',
    },
    axisLabel: {
      formatter: function (val) {
        return `${(val)} k`; // Convert to 'k' format
      },
    },
  },
  series: [
    {
      name: 'Train 1',
      type: 'line',
      data: train1.map((value) =>
        value === 0 || value == null ? '-' : (Math.round(value / 1000 * 100) / 100).toFixed(2)
      ),
    },
    {
      name: 'Train 2',
      type: 'line',
      data: train2.map((value) =>
        value === 0 || value == null ? '-' : (Math.round(value / 1000 * 100) / 100).toFixed(2)
      ),
    },
    {
      name: 'Total Daily Flow',
      type: 'line',
      data: dailyFlow.map((value) =>
        value === 0 || value == null ? '-' : (Math.round(value / 1000 * 100) / 100).toFixed(2)
      ),
    },
  ],
};

